# Vertices 0..10
# We can create a graph that is almost 3-regular but with one vertex of degree 4.

# One approach: take a 3-regular graph on 10 vertices (e.g., Petersen graph?) and add an 11th vertex connected to 3 vertices, but then those 3 vertices get degree 4. That would give 3 vertices degree 4, others degree 3. Sum = 3*4 + 8*3 = 12+24=36, edges=18.

# Let's just use Python to search for a random graph.

import random

def has_min_degree(adj, min_deg):
    return all(len(neighbors) >= min_deg for neighbors in adj)

def random_graph(n, min_deg, max_attempts=10000):
    for _ in range(max_attempts):
        adj = [set() for _ in range(n)]
        # Start with a cycle to ensure connectivity and base degree 2
        for i in range(n):
            j = (i+1) % n
            adj[i].add(j)
            adj[j].add(i)
        # Add random edges until min degree satisfied
        possible_edges = [(i,j) for i in range(n) for j in range(i+1, n) if j not in adj[i]]
        random.shuffle(possible_edges)
        for i,j in possible_edges:
            if len(adj[i]) < min_deg or len(adj[j]) < min_deg:
                adj[i].add(j)
                adj[j].add(i)
        if has_min_degree(adj, min_deg):
            return adj
    return None

adj = random_graph(11, 3)
if adj:
    edges = []
    for i in range(11):
        for j in adj[i]:
            if i < j:
                edges.append((i,j))
    print("Edges:", edges)
    print("Degrees:", [len(adj[i]) for i in range(11)])
else:
    print("Not found")
